import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice returns a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);

  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
  assert.equal(r.value.lines[1].unitPrice, 120000);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '10/07/2026',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-7',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: 'not-a-date',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for impossible dates', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns NO_LINES for missing lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 5.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: '5' }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns QTY_INVALID for zero or negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: -1 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns UNKNOWN_SKU for invalid SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'NONEXISTENT', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice validates all lines before returning error', () => {
  // First line is good, second line has bad SKU - should return UNKNOWN_SKU
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID', qty: 2 },
    ],
  });

  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice handles products with different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate input arguments', () => {
  const lines = [
    { sku: 'DEV-HOUR', qty: 5 },
    { sku: 'LOGO-PACK', qty: 1 },
  ];
  const linesCopy = JSON.parse(JSON.stringify(lines));

  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });

  assert.deepEqual(lines, linesCopy);
});

test('lineTotal multiplies quantity by unit price', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal works with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('lineTotal works with large numbers', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 999900 }), 999900000);
});

test('invoiceTotals calculates subtotal and total from a single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 47500, total: 47500 });
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
      { qty: 100, unitPrice: 37 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 47500 + 120000 + 3700);
  assert.equal(totals.total, 47500 + 120000 + 3700);
  assert.equal(totals.subtotal, 171200);
  assert.equal(totals.total, 171200);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, total: 0 });
});

test('invoiceTotals matches createInvoice result', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const totals = invoiceTotals(invoice);

  const expectedDev = 5 * 9500;
  const expectedLogo = 1 * 120000;
  assert.equal(totals.subtotal, expectedDev + expectedLogo);
  assert.equal(totals.total, expectedDev + expectedLogo);
});

test('invoiceTotals does not mutate the invoice', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, invoiceCopy);
});

test('addLine adds a new line to the invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 2);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[1].sku, 'LOGO-PACK');
  assert.equal(newInvoice.lines[1].qty, 1);
  assert.equal(newInvoice.lines[1].name, 'Logo package');
  assert.equal(newInvoice.lines[1].unitPrice, 120000);
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(newInvoice.lines[0].qty, 8);
});

test('addLine returns NOT_DRAFT if invoice is not in draft status', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'finalized',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const result = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine returns QTY_INVALID for invalid quantity', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;

  assert.deepEqual(
    addLine(invoice, { sku: 'LOGO-PACK', qty: 0 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    addLine(invoice, { sku: 'LOGO-PACK', qty: -1 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    addLine(invoice, { sku: 'LOGO-PACK', qty: 5.5 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('addLine returns UNKNOWN_SKU for invalid SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'NONEXISTENT', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });

  assert.deepEqual(invoice, invoiceCopy);
});

test('removeLine removes a line from the invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.equal(result.ok, true);

  const newInvoice = result.value;
  assert.equal(newInvoice.lines.length, 1);
  assert.equal(newInvoice.lines[0].sku, 'LOGO-PACK');
});

test('removeLine returns NOT_DRAFT if invoice is not in draft status', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'finalized',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
      { sku: 'LOGO-PACK', qty: 1, name: 'Logo package', unitPrice: 120000, vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine returns LINE_NOT_FOUND if SKU is not on the invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;

  const result = removeLine(invoice, 'NONEXISTENT');
  assert.deepEqual(result, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;

  const result = removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('removeLine does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  const invoice = invoiceResult.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  removeLine(invoice, 'DEV-HOUR');

  assert.deepEqual(invoice, invoiceCopy);
});

test('addLine and removeLine maintain invoice structure', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;

  const withNewLine = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }).value;
  assert.equal(withNewLine.customerId, 'C-001');
  assert.equal(withNewLine.issueDate, '2026-10-07');
  assert.equal(withNewLine.status, 'draft');

  const withoutLine = removeLine(withNewLine, 'LOGO-PACK').value;
  assert.equal(withoutLine.customerId, 'C-001');
  assert.equal(withoutLine.issueDate, '2026-10-07');
  assert.equal(withoutLine.status, 'draft');
  assert.equal(withoutLine.lines.length, 1);
});

