test('issueInvoice sets number and changes status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  const existing = [];

  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);

  const issuedInvoice = result.value;
  assert.equal(issuedInvoice.number, 'INV-2026-0001');
  assert.equal(issuedInvoice.status, 'issued');
  assert.equal(issuedInvoice.customerId, 'C-001');
  assert.equal(issuedInvoice.issueDate, '2026-10-07');
  assert.equal(issuedInvoice.lines.length, 1);
});

test('issueInvoice increments number from existing invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  const existing = ['INV-2026-0001', 'INV-2026-0003'];

  const result = issueInvoice(invoice, existing);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0004');
});

test('issueInvoice uses different counter for different years', () => {
  const invoice2025 = {
    customerId: 'C-001',
    issueDate: '2025-12-31',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const invoice2026 = {
    customerId: 'C-001',
    issueDate: '2026-01-01',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const existing = ['INV-2025-0010', 'INV-2026-0005'];

  const result2025 = issueInvoice(invoice2025, existing);
  assert.equal(result2025.value.number, 'INV-2025-0011');

  const result2026 = issueInvoice(invoice2026, existing);
  assert.equal(result2026.value.number, 'INV-2026-0006');
});

test('issueInvoice returns NOT_DRAFT if invoice is not in draft status', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = invoiceResult.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  issueInvoice(invoice, []);

  assert.deepEqual(invoice, invoiceCopy);
});

test('issueInvoice preserves all invoice data except status and adds number', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DESIGN-HOUR', qty: 5 },
    ],
  });

  const invoice = invoiceResult.value;
  const result = issueInvoice(invoice, ['INV-2026-0001', 'INV-2026-0002']);

  assert.equal(result.ok, true);
  const issued = result.value;

  assert.equal(issued.customerId, 'C-003');
  assert.equal(issued.issueDate, '2026-10-15');
  assert.equal(issued.number, 'INV-2026-0003');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.lines.length, 2);
  assert.equal(issued.lines[0].sku, 'DEV-HOUR');
  assert.equal(issued.lines[0].qty, 10);
  assert.equal(issued.lines[1].sku, 'DESIGN-HOUR');
});

